use super::*;
use crate::llm::codex::{
    build_input_with_reasoning_updates, build_request_body_with_tool_search, CodexStreamOptions,
};
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};

fn message(id: &str, role: &str, content: &str) -> ChatMessage {
    serde_json::from_value(json!({"id":id,"role":role,"content":content,"createdAt":0})).unwrap()
}

fn assert_reference_web_contract(tool: &Value) {
    use sha2::{Digest, Sha256};
    // Generated by the actual schema + JsonSchema serializer in codex
    // 82e70121f86bc1f6fea7f2bb7bbc169d259b3c6b. Independent of our tool loader:
    // changing a reserved-tool description or constraint must not silently pass.
    let fingerprint: String = Sha256::digest(serde_json::to_vec(tool).unwrap())
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect();
    assert_eq!(
        fingerprint, "f67597d3df3f3a77cb517646508e7305804ea029c6f8b1c1c1f241f0de0b214f",
        "web.run must match the reference contract; run scripts/sync-codex-web-tool.mjs --check"
    );
}

#[test]
fn native_web_reserved_contract_survives_http_websocket_and_lite_serialization() {
    assert_reference_web_contract(&tool_spec());
    for model in ["gpt-5.6-sol", "gpt-6-astra"] {
        for tool_search in [None, Some("Load tools")] {
            let body = build_request_body_with_tool_search(
                model,
                "test",
                &[message("u", "user", "hello")],
                &[tool_spec()],
                tool_search,
                None,
                Some("session"),
                None,
                CodexStreamOptions::default(),
            );
            for websocket in [false, true] {
                let wire = super::super::build_websocket_transport_request(&body, None, websocket);
                assert_eq!(
                    wire["type"].as_str(),
                    websocket.then_some("response.create")
                );
                let tools = if super::super::protocol::uses_lite(model) {
                    &wire["input"][0]["tools"]
                } else {
                    &wire["tools"]
                };
                let native: Vec<_> = tools
                    .as_array()
                    .unwrap()
                    .iter()
                    .filter(|tool| is_tool_spec(tool))
                    .collect();
                assert_eq!(native.len(), 1);
                assert_reference_web_contract(native[0]);
            }
        }
    }
}

#[test]
fn native_web_request_carries_commands_and_bounded_recent_text_only() {
    let history = vec![
        message("old", "user", "old secret"),
        message("previous", "user", "Previous question"),
        message("assistant", "assistant", &"中文🙂".repeat(5000)),
        message("tool", "tool", "do not send tools"),
        message("current", "user", "Read https://example.com/"),
        message("partial", "assistant", "current commentary"),
    ];
    let body = request_body(
        "session",
        "openai/gpt-6-astra",
        &history,
        &json!({
            "open":[{"ref_id":"https://example.com/","lineno":5}],
            "click":[{"ref_id":"turn0view0","id":7}],
            "find":[{"ref_id":"turn0view0","pattern":"text"}],"response_length":"long"
        }),
    )
    .unwrap();
    assert_eq!(body["model"], "gpt-6-astra");
    assert_eq!(
        body["settings"],
        json!({"external_web_access":true,"allowed_callers":["direct"]})
    );
    assert_eq!(body["input"].as_array().unwrap().len(), 3);
    assert_eq!(body["input"][0]["content"][0]["text"], "Previous question");
    assert!(
        crate::compact::estimate_text_tokens(
            body["input"][1]["content"][0]["text"].as_str().unwrap()
        ) <= 1000
    );
    assert!(!body.to_string().contains("old secret"));
    assert!(!body.to_string().contains("do not send tools"));
    assert!(!body.to_string().contains("current commentary"));
    assert_eq!(body["commands"]["click"][0]["ref_id"], "turn0view0");
    for input in [
        json!({}),
        json!({"open":[]}),
        json!({"url":"https://example.com/"}),
        json!({"open":[{"ref_id":"url","lineno":-1}]}),
        json!({"find":[{"ref_id":"url"}]}),
    ] {
        assert!(request_body("s", "m", &[], &input).is_err(), "{input}");
    }
}

#[test]
fn native_web_normal_and_lite_requests_replace_hosted_and_local_fetch_schemas() {
    let tools = vec![
        tool_spec(),
        json!({"type":"function","function":{"name":"web_fetch","parameters":{}}}),
    ];
    for model in ["gpt-5.6-sol", "gpt-6-astra"] {
        let body = build_request_body_with_tool_search(
            model,
            "test",
            &[],
            &tools,
            Some("Load tools"),
            None,
            Some("session"),
            None,
            CodexStreamOptions::default(),
        );
        let actual = if super::super::protocol::uses_lite(model) {
            &body["input"][0]["tools"]
        } else {
            &body["tools"]
        };
        assert!(actual.as_array().unwrap().iter().any(is_tool_spec));
        assert!(!actual.to_string().contains("\"name\":\"web_fetch\""));
        assert!(!actual
            .as_array()
            .unwrap()
            .iter()
            .any(|tool| tool["type"] == "web_search"));
    }
    let mut restored = vec![
        json!({"type":"tool_search_output","tools":[
            {"type":"namespace","name":"functions","tools":[{"type":"function","name":"web_fetch"},{"type":"function","name":"read"}]}
        ]}),
        json!({"type":"function_call","name":"web_fetch","arguments":"historical call"}),
    ];
    remove_local_fetch_from_history(&mut restored);
    assert_eq!(
        restored[0]["tools"][0]["tools"],
        json!([{"type":"function","name":"read"}])
    );
    assert_eq!(
        restored[1]["name"], "web_fetch",
        "actual history must not be rewritten"
    );
}

#[test]
fn native_web_streamed_calls_and_rebuilt_history_keep_the_namespace() {
    use super::super::{collect_complete_tool_calls, process_sse_event_block, CodexStreamState};
    let item = json!({"type":"function_call","id":"fc_web","call_id":"call_web","namespace":"web","name":"run",
        "arguments":r#"{"open":[{"ref_id":"https://example.com/"}]}"#});
    let mut state = CodexStreamState::new();
    process_sse_event_block(
        &format!(
            "data:{}",
            json!({"type":"response.output_item.done","item":item})
        ),
        false,
        &mut state,
        &|_| {},
        &|_| {},
        &|_, _| {},
    )
    .unwrap();
    let (calls, incomplete) = collect_complete_tool_calls(&state.tool_calls_map);
    assert_eq!(incomplete, 0);
    let call = calls[0].tool_call.clone();
    assert_eq!(call.name, TOOL_NAME);
    assert!(
        !call.is_server_tool(),
        "standalone calls need a persisted function output"
    );
    let mut assistant = message("assistant", "assistant", "");
    assistant.tool_calls = Some(vec![call]);
    let mut result = message("tool", "tool", "native page content with turn0view0");
    result.tool_call_id = Some("call_web".into());
    let history = [message("user", "user", "Read the page"), assistant, result];
    let rebuilt = build_input_with_reasoning_updates(&history, None, false);
    let call = rebuilt
        .iter()
        .find(|item| item["type"] == "function_call")
        .unwrap();
    assert_eq!(call["namespace"], "web");
    assert_eq!(call["name"], "run");
    assert_eq!(
        rebuilt.last().unwrap()["output"],
        "native page content with turn0view0"
    );
    let metadata = super::super::protocol::response_metadata(
        json!({}),
        &[item],
        "",
        history[1].tool_calls.as_ref().unwrap(),
        &json!({}),
    );
    let metadata = std::collections::HashMap::from([("assistant".into(), metadata)]);
    let replayed = build_input_with_reasoning_updates(&history, Some(&metadata), false);
    assert_eq!(
        replayed
            .iter()
            .find(|item| item["type"] == "function_call")
            .unwrap()["namespace"],
        "web"
    );
}

async fn read_request(
    socket: &mut tokio::net::TcpStream,
) -> (String, std::collections::HashMap<String, String>, Value) {
    let mut reader = BufReader::new(socket);
    let mut line = String::new();
    reader.read_line(&mut line).await.unwrap();
    let request_line = line.clone();
    let mut headers = std::collections::HashMap::new();
    loop {
        line.clear();
        assert_ne!(reader.read_line(&mut line).await.unwrap(), 0);
        if line == "\r\n" {
            break;
        }
        let (name, value) = line.split_once(':').unwrap();
        headers.insert(name.to_ascii_lowercase(), value.trim().to_string());
    }
    let mut bytes = vec![0; headers["content-length"].parse().unwrap()];
    reader.read_exact(&mut bytes).await.unwrap();
    if headers
        .get("content-encoding")
        .is_some_and(|value| value == "zstd")
    {
        bytes = zstd::stream::decode_all(bytes.as_slice()).unwrap();
    }
    (
        request_line,
        headers,
        serde_json::from_slice(&bytes).unwrap(),
    )
}

async fn reply(socket: &mut tokio::net::TcpStream, status: u16, body: &Value) {
    let body = body.to_string();
    socket.write_all(format!("HTTP/1.1 {status} Test\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.len()).as_bytes()).await.unwrap();
}

#[tokio::test]
async fn native_web_http_reuses_oauth_refreshes_once_and_forwards_open_find_references() {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!(
        "http://{}/backend-api/codex/responses",
        listener.local_addr().unwrap()
    );
    let server = tokio::spawn(async move {
        let mut requests = Vec::new();
        for (status, output) in [
            (401, json!({"error":"expired"})),
            (
                200,
                json!({"output":"[Page](https://example.com/) turn0view0", "results":[{"type":"text"}]}),
            ),
            (200, json!({"output":"Found text in turn0view0"})),
        ] {
            let (mut socket, _) = listener.accept().await.unwrap();
            requests.push(read_request(&mut socket).await);
            reply(&mut socket, status, &output).await;
        }
        requests
    });
    let mut refreshes = Vec::new();
    let body = request_body(
        "session",
        "gpt-6-astra",
        &[],
        &json!({"open":[{"ref_id":"https://example.com/"}]}),
    )
    .unwrap();
    let output = execute(Some(&base), &body, |refresh| {
        refreshes.push(refresh);
        async move {
            Ok((
                if refresh { "new-token" } else { "old-token" }.into(),
                Some("account".into()),
            ))
        }
    })
    .await
    .unwrap();
    assert_eq!(refreshes, vec![false, true]);
    assert!(output.contains("turn0view0"));
    let find = request_body(
        "session",
        "gpt-6-astra",
        &[],
        &json!({"find":[{"ref_id":"turn0view0","pattern":"text"}]}),
    )
    .unwrap();
    execute(Some(&base), &find, |_| async {
        Ok(("new-token".into(), Some("account".into())))
    })
    .await
    .unwrap();
    let requests = server.await.unwrap();
    assert!(requests
        .iter()
        .all(|(path, _, _)| path.starts_with("POST /backend-api/codex/alpha/search ")));
    assert_eq!(requests[0].1["authorization"], "Bearer old-token");
    assert_eq!(requests[1].1["authorization"], "Bearer new-token");
    assert_eq!(requests[1].1["chatgpt-account-id"], "account");
    assert_eq!(
        requests[0].2, requests[1].2,
        "refresh must not change commands or context"
    );
    assert_eq!(requests[2].2["commands"]["find"][0]["ref_id"], "turn0view0");
    assert_eq!(requests[2].2["id"], requests[1].2["id"]);
}

#[tokio::test]
async fn native_web_failures_never_fall_back_or_retry_non_auth_errors() {
    for (status, body) in [
        (403, json!({"error":"not allowed"})),
        (404, json!({"error":"unsupported"})),
        (500, json!({"error":"upstream failed"})),
        (200, json!({"unexpected":"missing output"})),
    ] {
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let base = format!("http://{}", listener.local_addr().unwrap());
        let server = tokio::spawn(async move {
            let (mut socket, _) = listener.accept().await.unwrap();
            let (path, _, _) = read_request(&mut socket).await;
            assert!(path.starts_with("POST /alpha/search "));
            reply(&mut socket, status, &body).await;
        });
        let mut resolves = 0;
        let result = execute(
            Some(&base),
            &json!({"commands":{"open":[{"ref_id":"https://example.com/"}]}}),
            |refresh| {
                assert!(!refresh);
                resolves += 1;
                async { Ok(("test-token".into(), None)) }
            },
        )
        .await;
        assert!(result.is_err());
        assert_eq!(resolves, 1);
        server.await.unwrap();
    }
}

#[test]
fn native_web_endpoint_follows_the_existing_provider_root_rules() {
    for base in [
        None,
        Some("https://chatgpt.com/backend-api"),
        Some("https://chatgpt.com/backend-api/codex/responses/"),
    ] {
        assert_eq!(
            endpoint(base),
            "https://chatgpt.com/backend-api/codex/alpha/search"
        );
    }
    assert_eq!(
        endpoint(Some("https://gateway.example/prefix/v1/")),
        "https://gateway.example/prefix/v1/alpha/search"
    );
}
